"""Cinematic community overview and dedicated Clubhouse presentation."""
hero_alts.update({'clubhouse':'Stone and timber Clubhouse and full-size pool in a tropical mountain garden','landscape':'Private mountain homes among lush gardens and woodland'})
pages['vision.html']=('The vision',
 hero('landscape','The Mount Paradise vision','Room for yourself.<br><em>A place to belong.</em>','Private homes in the trees. A Clubhouse at the heart. A landscape that brings them together.')
 +f'''<section class="section feature" id="discover">{pic('interior','Warm teak and volcanic stone interior opening to lush gardens','Stone, timber and light · Architectural concept')}<div class="feature-copy"><p class="eyebrow">Rooted in the mountains</p><h2>Built around<br>what matters.</h2><p>Natural stone. Substantial timber. Deep verandas that draw life outdoors. The existing pilot inspires a family of homes shaped around gardens, privacy and time together.</p>{link('lodges.html','Explore cabins and lodges')}</div></section>
 <section class="section dark"><div class="section-heading"><div><p class="eyebrow">The shared heart</p><h2>Your place.<br>Our Clubhouse.</h2></div>{link('clubhouse.html','Step inside the Clubhouse')}</div>{pic('clubhouse','Proposed Clubhouse overlooking its swimming pool and mountain gardens','The Clubhouse · Phase 2 concept')}<p class="image-story">A morning swim, a game of tennis, a long lunch on the terrace. The Clubhouse brings recreation, wellness and good company into the rhythm of mountain life.</p></section>
 <section class="section feature">{pic('mountain-cabin','A compact stone and timber cabin in its own fern garden','Mountain Cabin · Architectural concept')}<div class="feature-copy"><p class="eyebrow">A home at your scale</p><h2>Small escape.<br>Generous life.</h2><p>Begin with a Mountain Cabin, or explore the Retreat, Family, Reserve and Estate lodges. Each has a private relationship with the garden and a shared connection to the wider sanctuary.</p>{link('lodge-tiers.html','Compare the collection')}</div></section>
 <section class="section plan-preview" id="private-sanctuary"><div class="section-heading"><div><p class="eyebrow">Within the gates</p><h2>Take the scenic<br>way home.</h2></div></div>{pic('terrace','A sheltered mountain veranda surrounded by abundant planting','A slower mountain rhythm · Lifestyle concept')}<div class="thirds">{row('Arrive','A private approach','A dedicated gated entrance and controlled arrival are planned for residents and their guests.')}{row('Explore','Through the gardens','Stone roads for golf carts and places to walk connect private homes with the Clubhouse.')}{row('Return','Your own quiet corner','A porch, a veranda or a garden terrace. A personal place to pause at the end of the day.')}</div></section>
 <section class="section" id="community-lodge"><div class="split"><h2>One vision.<br>Three chapters.</h2><div><p>The built pilot is the starting point. Phase 2 extends the community across 10 hectares, with a future expansion opportunity of 20+ hectares in Phase 3.</p>{link('land.html','Explore the land')}<br><span id="club-membership">{link('clubhouse.html#membership','Explore Club Membership')}</span></div></div></section>''')
pages['clubhouse.html']=('The Clubhouse',
 hero('clubhouse','The Clubhouse / Mount Paradise','The heart of<br><em>the mountain.</em>','Swim. Play. Restore. Gather. A shared home within your mountain sanctuary.')
 +f'''<section class="section intro" id="discover"><p class="eyebrow">A place to come together</p><div class="split"><h2>Make a day of it.</h2><div class="prose"><p>The proposed Clubhouse anchors the 10-hectare Phase 2 community. Generous stone and timber spaces open to gardens and a full-size pool, with room for familiar faces and everyday rituals.</p></div></div><div class="club-index"><a href="#swim-play">Swim &amp; play ↓</a><a href="#spa">Spa &amp; baths ↓</a><a href="#dining">Restaurant &amp; café ↓</a><a href="#membership">Membership ↓</a></div></section>
 <section class="section dark" id="swim-play"><div class="section-heading"><div><p class="eyebrow">Movement / Open air</p><h2>A swim before breakfast.<br>A match before lunch.</h2></div></div>{pic('clubhouse','Full-size pool with the stone and timber Clubhouse beyond','The pool terrace · Proposed Clubhouse concept')}<div class="split image-copy"><div><h3>The full-size pool</h3><p>Space for a proper swim, with a landscaped terrace for resting between dips and the Clubhouse just a few steps away.</p></div><div><h3>The tennis court</h3><p>A dedicated court is planned alongside the club facilities. Meet for a morning rally, then carry the conversation onto the terrace.</p></div></div></section>
 <section class="section feature" id="spa">{pic('clubhouse-spa','Stone bathing pools beneath teak beams opening onto a lush mountain forest','Spa & baths · Proposed Clubhouse concept')}<div class="feature-copy"><p class="eyebrow">Wellness / A quieter hour</p><h2>Let the world<br>wait a little.</h2><p>Bathing pools, warm materials and garden views create the setting for a slower ritual. The proposed spa offers a quiet counterpoint to a day outdoors.</p><p>Spaces for treatments and bathing will be developed alongside the Clubhouse design.</p></div></section>
 <section class="section dark" id="dining"><div class="section-heading"><div><p class="eyebrow">The restaurant &amp; café</p><h2>Your favorite table.<br>Close to home.</h2></div></div>{pic('dining','Sheltered stone and timber dining terrace opening to tropical gardens','Garden dining · Clubhouse atmosphere and material direction')}<p class="image-story">Coffee after a walk. Lunch beneath the eaves. Dinner as the garden lights come on. An intimate restaurant and café is planned as part of the Clubhouse, with attentive hospitality and a relaxed mountain setting.</p></section>
 <section class="section feature">{pic('interior','Warm timber lounge with linen seating and open garden views','Lounge atmosphere · Clubhouse material direction')}<div class="feature-copy"><p class="eyebrow">The members’ lounge</p><h2>Stay for<br>the conversation.</h2><p>A comfortable chair, a book and room for friends. Shared lounges and sheltered terraces make the Clubhouse a place to drop into throughout the day.</p><p>Private homes keep their own quiet rhythm, with a social world close by.</p></div></section>
 <section class="section plan-preview" id="membership"><p class="eyebrow">Club Membership / In development</p><div class="split"><h2>A shared part<br>of mountain life.</h2><div><p>Club Membership is envisioned as the route to the Clubhouse and its recreation and wellness facilities, complementing the privacy of your own cabin or lodge.</p><p class="note">Membership eligibility, fees, guest access, dining and spa arrangements are being developed. Facilities shown are proposed concepts for Phase 2.</p>{link('lodges.html','Find your mountain home')}</div></div></section>''')
